809:        dir + INSTALL_LIST_CONFIG, installList_);
810:    bundleParser.ParsePreInstallConfig(
811:        dir + APP_SERVICE_FWK_INSTALL_LIST_CONFIG, systemHspList_);
812:    bundleParser.ParsePreInstallConfig(
813:        dir + SKILLS_INSTALL_LIST_CONFIG, skillsList_);
814:    bundleParser.ParsePreUnInstallConfig(
815:        dir + UNINSTALL_LIST_CONFIG, uninstallList_);
816:    bundleParser.ParsePreInstallAbilityConfig(
817:        dir + INSTALL_LIST_CAPABILITY_CONFIG, installListCapabilities_);
818:    bundleParser.ParseExtTypeConfig(
819:        dir + EXTENSION_TYPE_LIST_CONFIG, extensiontype_);
820:    bundleParser.ParsePreInstallConfig(
821:        dir + SHARED_BUNDLES_INSTALL_LIST_CONFIG, installList_);
822:    bundleParser.ParseDemandInstallConfig(dir + INSTALL_LIST_CONFIG, onDemandInstallList_);
823:
824:    std::string oldSystemFingerprint = GetOldSystemFingerprint();
825:    if (oldSystemFingerprint.empty()) {
826:        LOG_W(BMS_TAG_DEFAULT, "only scan app_list.json on first startup");
827:        bundleParser.ParsePreAppListConfig(dir + ServiceConstants::DEFAULT_DATA_PRE_BUNDLE_DIR, installList_,
